INSERT INTO public.ai_prompt_rules (escopo, conteudo, ordem, ativo, observacao)
VALUES
('global', 'FLUXO OBRIGATÓRIO A CADA NOVA SOLICITAÇÃO DE PACOTE (mesmo com os dados no histórico, NUNCA pule): 1) confirmar origem + passageiros + período + duração citando o destino ("Claro! Para Porto Seguro, continuam sendo 2 pessoas saindo de Curitiba? E mantenho dezembro, com aproximadamente 6 noites?"); 2) esperar a resposta; 3) mandar a transição antes de pesquisar ("Perfeito! Vou verificar as opções de Porto Seguro com essas condições e já te mostro 😊"); 4) buscar; 5) enviar o card; 6) SEMPRE fechar com continuidade comercial, o card NUNCA pode ser a última mensagem: "Essa é uma opção pronta que temos nessas condições. O que achou? Se quiser, também posso procurar outras datas, hotéis ou personalizar o pacote para vocês.".', 26, true, 'Auditoria: Porto Seguro 21:35');